// План specs/dashboard.md 3.6 (кейс DB-13). Десктоп 1440, admin, компания «test». Только просмотр (@prod-safe).
// Работа с несколькими техниками засчитывается только ведущему (Lead). Устойчиво к смене данных:
// ни одна работа не встречается в разбивках двух техников одновременно (на 14.10.26: JOB-0084 — у Owen Brooks, не у Kirill).
import { test, expect } from '@playwright/test';
import { ADMIN_STATE } from '../addresses/address-helpers';
import {
  chooseRange, closeBreakdown, expectRowsMatchRpc, openBreakdown, openDashboardTeam, readBreakdown, readTeamRows,
  teamWidget, trackDashboardRpc,
} from './team-performance-helpers';

test.use({ storageState: ADMIN_STATE });

test.describe('Дашборд, Team Performance: работа нескольких техников — только ведущему (#5814749d)', () => {
  test('Desktop Team Performance EN: Last 90 days — no job appears in the breakdowns of two technicians #5814749d @desktop @prod-safe', async ({ page }) => {
    const rpc = trackDashboardRpc(page);
    await openDashboardTeam(page, 'en');
    await rpc.teamFor(30);
    await chooseRange(page, teamWidget(page, 'en'), 'en', 90, 'team');
    await expectRowsMatchRpc(page, 'en', await rpc.teamFor(90));
    const rows = await readTeamRows(page, 'en');
    expect(rows.length, 'нужны хотя бы два техника с работами за 90 дней').toBeGreaterThanOrEqual(2);

    const owner = new Map<string, string>(); // номер работы → техник
    const dupes: string[] = [];
    for (const row of rows) {
      const dlg = await openBreakdown(page, 'en', row);
      const jobs = await readBreakdown(dlg);
      for (const j of jobs) {
        expect(j.jobNo, `номер работы в разбивке ${row.name}: ${j.text}`).not.toBe('');
        const prev = owner.get(j.jobNo);
        if (prev && prev !== row.name) dupes.push(`${j.jobNo}: ${prev} и ${row.name}`);
        owner.set(j.jobNo, row.name);
      }
      // В своей разбивке работа тоже не дублируется.
      expect(new Set(jobs.map((j) => j.jobNo)).size, `без повторов в разбивке ${row.name}`).toBe(jobs.length);
      await closeBreakdown(dlg);
    }
    expect(dupes, 'работа засчитана только одному (ведущему) технику').toEqual([]);
  });
});
